(*
 * Startup Warning - warn first, then start the motor after a delay kept in a TIME variable.
 *)

PROGRAM StartupWarning

VAR_INPUT
    StartButton AT %IX0.0 : BOOL;
    StopButton AT %IX0.1 : BOOL;
END_VAR

VAR
    Requested : BOOL;               (* memory bit: no address *)
    WarnTimer : TON;
    WarnTime : TIME := T#50ms;
END_VAR

VAR_OUTPUT
    WarningLamp AT %QX0.0 : BOOL;
    Motor AT %QX0.1 : BOOL;
END_VAR

Requested := (StartButton OR Requested) AND NOT StopButton;
WarnTimer(IN := Requested, PT := WarnTime);
WarningLamp := Requested;
Motor := WarnTimer.Q;

END_PROGRAM

